"""Read-only coverage audit. Freeze specification before weight outcomes are computed."""
import sys,json,csv,hashlib,time
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'src'))
import torch,yaml
O=ROOT/'results/expert_exposure_weight_development_v1';SEEDS=[7,17,29,43,61];STEPS=[0,250,500,1000,1750,2500]
def sha(p):
 h=hashlib.sha256()
 with Path(p).open('rb') as f:
  for b in iter(lambda:f.read(8<<20),b''):h.update(b)
 return h.hexdigest()
def save(p,x):Path(p).write_text(json.dumps(x,indent=2,allow_nan=False)+'\n')
def table(p,rows):
 keys=list(dict.fromkeys(k for r in rows for k in r))
 with Path(p).open('w') as f:w=csv.DictWriter(f,keys);w.writeheader();w.writerows(rows)
def source(s):return ROOT/(f'results/32e_router_age_localization/references/seed_{s}' if s in (7,17,29) else f'results/router_conditioned_fixed_budget_dataset/sources/e32/seed_{s}')
def main():
 O.mkdir(exist_ok=False);rows=[];coverage=[];paths={};seen={};configs=[];total=0
 for seed in SEEDS:
  d=source(seed);cfg=yaml.safe_load((d/'resolved_config.yaml').read_text());configs.append(cfg)
  exposure=[json.loads(l) for l in (d/'logs/training_exposure.jsonl').open()];assert [r['step'] for r in exposure]==list(range(1,2501))
  assert all(set(r['accepted'])==set(exposure[0]['accepted']) and all(0<=r['accepted'][e]<=r['proposed'][e] for e in r['accepted']) for r in exposure)
  applied=sum(r['optimizer_step_applied'] for r in exposure);paths[str(seed)]=str(d)
  coverage.append(dict(seed=seed,trajectory='original_source',log_path=str(d/'logs/training_exposure.jsonl'),sha256=sha(d/'logs/training_exposure.jsonl'),first_step=1,last_step=2500,logged_steps=len(exposure),attempted_updates=2500,applied_updates=applied,skipped_updates=2500-applied,proposed=True,accepted=True,dropped='proposed minus accepted',gate_weighted=False,accepted_token_composition=False,hidden_input_statistics=False,domain_labels=False,fixed_probe_assignments='250,500,750,1000,1250,1500,1750,2000,2250,2500',context_samples='first two proposed positions per expert per logging step; biased, no acceptance; excluded from composition features'))
  for p in sorted((d/'checkpoints').glob('step_*.pt'),key=lambda p:int(p.stem.split('_')[1])):
   step=int(p.stem.split('_')[1]);h=sha(p);dupe=seen.get(h,'');seen[h]=str(p);total+=p.stat().st_size
   rows.append(dict(seed=seed,architecture='32E 4L d256 hidden1024 top1',family='original_source',protocol='native unpruned AdamW FP16',checkpoint_step=step,path=str(p),sha256=h,hash_verified=True,duplicate_of=dupe,selected=step in STEPS,attempted_updates=step,applied_updates=sum(r['optimizer_step_applied'] for r in exposure[:step]),optimizer_reset_boundary=0,reason='all five compatible source seeds; common bounded six-point grid' if step in STEPS else 'additional checkpoint; outside fixed compute grid'))
  print('audited source',seed,flush=True)
 # Inventory distinct excluded protocol families from their existing immutable manifests.
 af=json.loads((ROOT/'results/imp_adaptation_factorial_v1/manifest.json').read_text())
 for v in af['variants']:
  if v['seed'] not in SEEDS:continue
  for label,p in [('initial',v['initial']),('full_attempt',v['full_attempt'])]:
   rows.append(dict(seed=v['seed'],architecture='32E',family='unpruned_recovery' if not v['sparsity'] else 'sparse_recovery',protocol='two native segments; optimizer reset at absolute2500',checkpoint_step='0,100,2500,2600,5000',path=p,sha256='',hash_verified=False,duplicate_of='initial aliases source step0 for dense; compare state hashes separately',selected=False,attempted_updates=5000,applied_updates='see segment records',optimizer_reset_boundary='0,2500',reason='distinct recovery family; not concatenated with source; excluded before outcomes'))
 for s in SEEDS:
  for d in sorted((ROOT/f'results/imp_80_85/trajectories/e32/seed_{s}').glob('round_*')):
   rows.append(dict(seed=s,architecture='32E',family='IMP_discovery_round',protocol=d.name,checkpoint_step=','.join(p.stem for p in sorted((d/'checkpoints').glob('*.pt'))),path=str(d),sha256='',hash_verified=False,selected=False,optimizer_reset_boundary='each round',reason='discovery/rewinding protocol; sparse except round00; not source training; outside selected family'))
 assert all(c['model']==configs[0]['model'] and c['data']==configs[0]['data'] and {k:c['training'][k] for k in ('steps','learning_rate','weight_decay','batch_size','precision')}=={k:configs[0]['training'][k] for k in ('steps','learning_rate','weight_decay','batch_size','precision')} for c in configs)
 table(O/'inventory.csv',rows);table(O/'exposure_coverage.csv',coverage)
 pairs=list(zip(STEPS[:-1],STEPS[1:]))+[(s,2500) for s in STEPS[1:-2]]
 # adjacent: 0-250,250-500,500-1000,1000-1750,1750-2500; long:250/500/1000-2500
 cfg=dict(retrospective_exploratory=True,selection_before_associations=True,source_seeds=SEEDS,source_paths=paths,primary_family='original unpruned native source training',architecture=configs[0]['model'],training=configs[0]['training'],checkpoint_steps=STEPS,pairs=pairs,initialization_reference_only=0,reset_crossing_pairs=[],ranking_units=['within_tensor','expert_joint_fc1_fc2'],identity=['trajectory_seed','layer','expert','parameter_name','row_major_index'],ties='ascending absolute magnitude then canonical fc1-before-fc2 row-major coordinate; unique ordinal ranks; actual torch.topk boundary ties separately audited',early_low_quantile=0.5,late_top_fractions=[0.20,0.15],transition_bins=[0,.2,.4,.6,.8,1.],coordinate_sampling=False,exact_all_coordinates=True,workers=4,memory_bound='CPU only; six mmap checkpoint handles per seed; process one expert at a time; <=4 concurrent experts; no GPU models or coordinate CSV',storage_estimate_mb=80,checkpoint_io_selected_gb=sum(rp.stat().st_size for s in SEEDS for st in STEPS for rp in [source(s)/f'checkpoints/step_{st}.pt'])/1e9,audit_all_source_io_gb=total/1e9,exposure_features=['log1p applied accepted rate in immediately preceding interval','log1p cumulative applied accepted count by t','change in log accepted rate versus prior interval','drop fraction in preceding interval','fixed-probe proposed-membership Jaccard turnover in preceding interval'],composition_unavailable=['accepted training token-ID distribution','gate-weighted counts','hidden-input statistics','domain labels'],baseline_features=['current mean absolute magnitude','initial mean absolute magnitude','current low-half mean magnitude','prior mean absolute growth per attempted step','prior late-rising fraction','prior top20 turnover','layer identity','tensor/ranking identity','current attempted step','outcome interval length','prior applied-update count'],prediction=dict(model='Ridge alpha=1.0 on expert-level late-rising fraction; standardized features; one-hot identity; predictions clipped [0,1]',validation='leave one source seed out; preprocessing fitted on training seeds only',minimum_seeds=5,minimum_nonzero_prior_intervals=2,outcome='fraction of early-low weights entering later top20',evaluation='unweighted expert mean squared error; seed is replication unit; report outcome prevalence and seed-mean null MSE',no_search=True),associations='within seed/layer/pair/ranking Spearman, then report per-seed strata summaries; no coordinate replication; no significance claims',weight_decay='AdamW 0.01; optimizer states absent, cannot isolate decay',manual_examples='first exact coordinate satisfying rank rise with absolute growth, and first rank rise without absolute growth; outcome-selected illustrative only')
 save(O/'analysis_config.json',cfg)
 (O/'provenance_and_exclusions.md').write_text('''# Coverage and cohort selection\n\nRetrospective exploratory audit completed before weight/exposure associations. All five existing 32E source seeds (7,17,29,43,61) are eligible; no performance selection. Original source training is native, unpruned, 2500 attempted FP16 AdamW steps. Source has no interior optimizer reset. Step0 is initialization only. Primary checkpoints use the common grid 0,250,500,1000,1750,2500 to bound CPU sorting. Extra 125-step checkpoints for the first three seeds are inventoried but excluded by coverage rule.\n\nRecovery, sparse recovery, reset continuations, and IMP discovery rounds are distinct families, inventoried from existing manifests and excluded before associations. Round00 is still discovery/recovery protocol, not original source. No checkpoint or log from these families is joined to source. Unselected families have path/step inventory but their large checkpoint files are not rehashed; missing hashes are explicit rather than invented. Selected original source checkpoints are byte-rehashed; bit-identical file duplicates are removed, and model-state duplicates against dense reset initializations are audited separately. Expert identities are never aligned across source seeds.\n\nFull per-attempt source exposure logs provide exact proposed and accepted counts and applied-update flags. Dropped=proposed-accepted. Cumulative counts use all steps, not sampled usage diagnostics. Gate-weighted exposure, historical accepted-token composition, hidden-input statistics, and domain labels are unavailable. Context snippets are deterministic first-two proposed assignments, lack acceptance, and cannot estimate accepted composition. Fixed validation assignments describe proposed membership on a fixed probe, not historical training-token inputs or accepted dispatch. Native routing changes can include shared-network development.\n\nRank sorting pools fc1 and fc2 under the repository expert-local budget; biases/shared weights are excluded. Coordinate identity is exact parameter name and row-major index. Deterministic ordinal tie handling is distinguished from unspecified torch.topk boundary ties. Final IMP masks are not used as usefulness labels. Hypothetical disagreements do not demonstrate pruning damage, and magnitude does not establish functional importance.\n''')
 print('SPECIFICATION FROZEN',flush=True)
if __name__=='__main__':main()
